// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "POST", "template": "/v1/users/sync", "require_user": false, "idempotent": true, "required_consents": [], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.api.users_sync > "Validate body"
// POST /v1/users/sync, called by the website server after login.
// Body: {external_auth_id (required), email, display_name, locale, jurisdiction_code}
const gw = $input.first().json;
const b = gw.ctx.body || {};
const allowed = ['external_auth_id', 'email', 'display_name', 'locale', 'jurisdiction_code'];
const details = [];
for (const k of Object.keys(b)) if (!allowed.includes(k)) details.push({ field: k, issue: 'unknown_field' });

const str = (k, max, re) => {
  const v = b[k];
  if (v === undefined || v === null) return '';
  if (typeof v !== 'string') { details.push({ field: k, issue: 'must_be_string' }); return ''; }
  const t = v.trim();
  if (t.length > max) details.push({ field: k, issue: 'too_long', max });
  else if (t && re && !re.test(t)) details.push({ field: k, issue: 'invalid_format' });
  return t;
};
const external_auth_id = str('external_auth_id', 255, /^[\x21-\x7e]+$/);
if (!external_auth_id) details.push({ field: 'external_auth_id', issue: 'required' });
const email = str('email', 254, /^[^\s@]+@[^\s@]+\.[^\s@]+$/).toLowerCase();
const display_name = str('display_name', 100, /^[^\u0000-\u001f\u007f]+$/);
const locale = str('locale', 35, /^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$/);
const jurisdiction_code = str('jurisdiction_code', 10, /^[A-Z]{2}(-[A-Z0-9]{1,3})?$/);

if (details.length) {
  return [{ json: { ok: false, status: 422, gw,
    error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details } } }];
}
return [{ json: { ok: true, gw, params: [external_auth_id, email, display_name, locale, jurisdiction_code] } }];

// wf.api.users_sync > "Build result"
// Input: the row returned by the upsert. Consent status for the purposes the
// platform requires before use (terms, privacy).
const gw = $('Validate body').first().json.gw;
const row = $input.first().json;
const REQUIRED = ['terms', 'privacy'];
const consents = row.consents || {};
const consent_required = REQUIRED.filter((p) => !(consents[p] && consents[p].granted === true));
return [{ json: {
  ok: true, gw, status: row.created ? 201 : 200, result_user_id: row.user_id,
  data: {
    user_id: row.user_id, created: row.created, role: row.role, locale: row.locale,
    jurisdiction_code: row.jurisdiction_code, consents, consent_required,
  },
} }];

// wf.api.users_sync > "Upsert failed"
// Error output of the upsert. Known constraint violations become client errors.
const gw = $('Validate body').first().json.gw;
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const msg = errorText($input.first().json);
// Postgres error text can contain the offending value (an email): never log it.
if (msg.includes('users_email_key') || (msg.includes('Key (email)=') && msg.includes('already exists'))) {
  return [{ json: { ok: false, gw, status: 409, error: { code: 'CONFLICT', message: 'This email is already linked to another account', details: [{ field: 'email' }] } } }];
}
if (msg.includes('users_jurisdiction_code_fkey') || msg.includes('is not present in table "jurisdictions"')) {
  return [{ json: { ok: false, gw, status: 422, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details: [{ field: 'jurisdiction_code', issue: 'unknown' }] } } }];
}
return [{ json: { ok: false, gw, status: 503, error: { code: 'UPSTREAM_UNAVAILABLE', message: 'A backend dependency is unavailable', details: [] }, log: { reason: 'database_error', detail: redactPg(msg).slice(0, 300) } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
